// Some portions generated by Claude Code
package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.concurrent.BrokenBarrierException;
import java.util.concurrent.CyclicBarrier;
import java.util.concurrent.atomic.AtomicInteger;

import org.eclipse.rdf4j.sail.lmdb.evaluation.LmdbNativeHedgeRace.Arm;
import org.eclipse.rdf4j.sail.lmdb.evaluation.LmdbNativeHedgeRace.State;
import org.junit.jupiter.api.Test;

/**
 * Pins the hedge race state machine: the CAS commit gate, loser tripping, watchdog single-shot semantics, the failure
 * lattice (backup failure never fails a healthy primary; primary failure adopts a healthy backup; both-fail propagates
 * the primary's throwable with the backup's suppressed), and abort/teardown edges.
 */
class LmdbNativeHedgeRaceTest {

	@Test
	void primaryCommitBeforeAnyLaunchCancelsTheTriggerAndWins() {
		LmdbNativeHedgeRace race = new LmdbNativeHedgeRace();
		AtomicInteger launches = new AtomicInteger();
		race.armWatchdog(1_000_000L, launches::incrementAndGet, null);
		assertTrue(race.tryCommit(Arm.PRIMARY));
		assertEquals(State.COMMITTED_PRIMARY, race.state());
		// a late trigger firing after the commit must not launch anything
		race.fireWatchdog();
		assertEquals(0, launches.get());
		assertFalse(race.tryCommit(Arm.BACKUP), "the loser cannot publish after the race resolved");
	}

	@Test
	void firedWatchdogLaunchesExactlyOnceAndBackupCanWin() {
		LmdbNativeHedgeRace race = new LmdbNativeHedgeRace();
		LmdbNativeProbeDeadline primary = LmdbNativeProbeDeadline.trippableOnly();
		race.primaryDeadline(primary);
		AtomicInteger launches = new AtomicInteger();
		race.armWatchdog(0L, launches::incrementAndGet, null);
		race.fireWatchdog();
		race.fireWatchdog();
		assertEquals(1, launches.get(), "the trigger is single-shot");
		assertEquals(State.HEDGE_STARTING, race.state());
		assertTrue(race.backupLaunched());
		assertEquals(State.BOTH_RUNNING, race.state());
		assertTrue(race.tryCommit(Arm.BACKUP));
		assertEquals(State.COMMITTED_BACKUP, race.state());
		assertTrue(primary.tripped(), "the winning commit trips the loser's deadline");
		assertFalse(race.tryCommit(Arm.PRIMARY));
	}

	@Test
	void primaryWinTripsTheRacingBackup() {
		LmdbNativeHedgeRace race = new LmdbNativeHedgeRace();
		LmdbNativeProbeDeadline backup = LmdbNativeProbeDeadline.trippableOnly();
		race.backupDeadline(backup);
		race.armWatchdog(0L, () -> {
		}, null);
		race.fireWatchdog();
		assertTrue(race.backupLaunched());
		assertTrue(race.tryCommit(Arm.PRIMARY));
		assertTrue(backup.tripped());
		assertFalse(race.tryCommit(Arm.BACKUP));
	}

	@Test
	void poolRejectionRevertsToAnUnhedgedPrimary() {
		LmdbNativeHedgeRace race = new LmdbNativeHedgeRace();
		race.armWatchdog(0L, () -> {
		}, null);
		race.fireWatchdog();
		assertEquals(State.HEDGE_STARTING, race.state());
		race.poolRejected();
		assertEquals(State.PRIMARY_ONLY, race.state());
		assertTrue(race.tryCommit(Arm.PRIMARY));
	}

	@Test
	void backupFailureNeverFailsAHealthyPrimary() {
		LmdbNativeHedgeRace race = new LmdbNativeHedgeRace();
		race.armWatchdog(0L, () -> {
		}, null);
		race.fireWatchdog();
		assertTrue(race.backupLaunched());
		assertTrue(race.backupFailed(new IllegalStateException("backup broke")),
				"the primary continues as if never hedged");
		assertEquals(State.BACKUP_FAILED, race.state());
		assertTrue(race.tryCommit(Arm.PRIMARY));
		assertEquals(State.COMMITTED_PRIMARY, race.state());
	}

	@Test
	void primaryFailureAdoptsAHealthyBackupAndBothFailPropagatesThePrimarys() {
		LmdbNativeHedgeRace race = new LmdbNativeHedgeRace();
		race.armWatchdog(0L, () -> {
		}, null);
		race.fireWatchdog();
		assertTrue(race.backupLaunched());
		IllegalStateException primaryBoom = new IllegalStateException("primary broke");
		assertTrue(race.primaryFailed(primaryBoom), "a healthy racing backup rescues the dispatch");
		assertEquals(State.PRIMARY_FAILED, race.state());
		assertTrue(race.tryCommit(Arm.BACKUP), "the backup adopts from PRIMARY_FAILED");

		LmdbNativeHedgeRace bothFail = new LmdbNativeHedgeRace();
		bothFail.armWatchdog(0L, () -> {
		}, null);
		bothFail.fireWatchdog();
		assertTrue(bothFail.backupLaunched());
		IllegalStateException first = new IllegalStateException("primary broke");
		IllegalStateException second = new IllegalStateException("backup broke");
		assertTrue(bothFail.primaryFailed(first));
		assertFalse(bothFail.backupFailed(second), "no arm is left to rescue");
		assertEquals(State.BOTH_FAILED, bothFail.state());
		Throwable propagated = bothFail.propagateBothFailed();
		assertSame(first, propagated);
		assertEquals(1, propagated.getSuppressed().length);
		assertSame(second, propagated.getSuppressed()[0]);
	}

	@Test
	void primaryFailureWithNoBackupYetFailsTheRace() {
		LmdbNativeHedgeRace race = new LmdbNativeHedgeRace();
		LmdbNativeProbeDeadline primary = LmdbNativeProbeDeadline.trippableOnly();
		race.primaryDeadline(primary);
		assertFalse(race.primaryFailed(new IllegalStateException("boom")), "nothing can rescue before a launch");
		assertEquals(State.BOTH_FAILED, race.state());
		assertNotNull(race.propagateBothFailed());
	}

	@Test
	void abortTripsBothArmsAndNothingPublishes() {
		LmdbNativeHedgeRace race = new LmdbNativeHedgeRace();
		LmdbNativeProbeDeadline primary = LmdbNativeProbeDeadline.trippableOnly();
		LmdbNativeProbeDeadline backup = LmdbNativeProbeDeadline.trippableOnly();
		race.primaryDeadline(primary);
		race.backupDeadline(backup);
		race.armWatchdog(0L, () -> {
		}, null);
		race.fireWatchdog();
		assertTrue(race.backupLaunched());
		race.abort();
		assertEquals(State.CLOSED, race.state());
		assertTrue(primary.tripped());
		assertTrue(backup.tripped());
		assertFalse(race.tryCommit(Arm.PRIMARY));
		assertFalse(race.tryCommit(Arm.BACKUP));
		race.abort();
		assertEquals(State.CLOSED, race.state(), "abort is idempotent");
	}

	@Test
	void abortDuringHedgeStartingStopsTheLaunch() {
		LmdbNativeHedgeRace race = new LmdbNativeHedgeRace();
		race.armWatchdog(0L, () -> {
		}, null);
		race.fireWatchdog();
		assertEquals(State.HEDGE_STARTING, race.state());
		race.abort();
		assertFalse(race.backupLaunched(), "a launch arriving after close must not run");
		assertEquals(State.CLOSED, race.state());
	}

	@Test
	void awaitBackupTerminationIsImmediateWhenNoBackupEverStarted() {
		LmdbNativeHedgeRace race = new LmdbNativeHedgeRace();
		assertTrue(race.tryCommit(Arm.PRIMARY));
		assertTrue(race.awaitBackupTermination(1L));
	}

	@Test
	void awaitBackupTerminationJoinsTheExitedBackup() {
		LmdbNativeHedgeRace race = new LmdbNativeHedgeRace();
		race.armWatchdog(0L, () -> {
		}, null);
		race.fireWatchdog();
		assertTrue(race.backupLaunched());
		assertFalse(race.awaitBackupTermination(1_000_000L), "a live backup has not exited");
		race.backupExited();
		assertTrue(race.awaitBackupTermination(1_000_000L));
	}

	@Test
	void exactlyOneArmWinsUnderContention() throws Exception {
		for (int round = 0; round < 10_000; round++) {
			LmdbNativeHedgeRace race = new LmdbNativeHedgeRace();
			race.armWatchdog(0L, () -> {
			}, null);
			race.fireWatchdog();
			assertTrue(race.backupLaunched());
			CyclicBarrier barrier = new CyclicBarrier(2);
			boolean[] wins = new boolean[2];
			Thread primary = new Thread(() -> {
				await(barrier);
				wins[0] = race.tryCommit(Arm.PRIMARY);
			});
			Thread backup = new Thread(() -> {
				await(barrier);
				wins[1] = race.tryCommit(Arm.BACKUP);
			});
			primary.start();
			backup.start();
			primary.join();
			backup.join();
			assertTrue(wins[0] ^ wins[1], "exactly one arm must win, round " + round);
		}
	}

	@Test
	void trippableOnlyDeadlineNeverExpiresUntilTripped() {
		LmdbNativeProbeDeadline deadline = LmdbNativeProbeDeadline.trippableOnly();
		assertFalse(deadline.expired(), "a trippable-only deadline must not report expiry on its own");
		deadline.trip();
		assertTrue(deadline.expired());
		assertTrue(deadline.tripped());
	}

	private static void await(CyclicBarrier barrier) {
		try {
			barrier.await();
		} catch (InterruptedException | BrokenBarrierException e) {
			throw new IllegalStateException(e);
		}
	}
}
